(()=>{
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-IN',{maximumFractionDigits:2});
const valid=s=>typeof s==='string'&&/^(NSE|BSE):[A-Z0-9&._-]{2,65}$/.test(s);
const checked=r=>r&&typeof r.strategy==='string'&&typeof r.status==='string'&&typeof r.reason==='string';
const blocked=e=>/rate limit|HTTP 429|code -429|login expired|login invalid|login expired or invalid|sign in again|not connected/i.test(e);
window.FyersStockScreener={mount(host,{onChart,onPlan}){
 let custom=[],universe=[],names=new Map(),quotes=new Map(),rows=new Map(),running=false,active=true,run=0,search=0,load=0,page=0,cursor=0,scanSymbols=[],startedAt=null,lastAt=null,mode='all',directoryAt=null,pending=false,pauseTimer=null,pauseResolve=null,storageFailed=false;
 try{const d=JSON.parse(localStorage.getItem('radar.fyersStockList')||'[]');if(Array.isArray(d))custom=[...new Set(d.filter(valid))].slice(0,20)}catch{}
 host.innerHTML='<div class="market-controls"><label>Scan universe<select id="fsScope"><option value="all">All NSE stocks</option><option value="custom">My saved list</option></select></label><button id="fsUniverse">Reload NSE directory</button></div><p id="fsUniverseStatus" role="status">Loading all NSE stocks from FYERS…</p><details id="fsCustom" hidden><summary>Manage my saved list (optional)</summary><div class="market-controls"><label>Stock name / ticker<input id="fsQuery" maxlength="80" placeholder="TCS or Tata Consultancy"></label><label>Exchange<select id="fsSegment"><option value="NSE_CM">NSE</option><option value="BSE_CM">BSE</option></select></label><button id="fsFind">Search stocks</button><label>Matching instruments<select id="fsMatches"><option value="">Search first</option></select></label><button id="fsAdd">Add selected stock</button></div><p id="fsSearchStatus" role="status"></p></details><div class="market-controls"><button id="fsScan">Start full NSE scan</button><button id="fsResume" disabled>Resume scan</button><button id="fsStop" disabled>Pause</button><button id="fsQuotes">Refresh quotes</button></div><p id="fsStatus" role="status">Load the directory, then start scanning. Keep this page open.</p><progress id="fsProgress" value="0" max="1" style="width:100%" aria-label="Stocks checked"></progress><p id="fsCoverage"></p><div class="market-controls"><label>Find in universe<input id="fsTableSearch" placeholder="Company or ticker"></label><label>Show<select id="fsFilter"><option value="all">All stocks</option><option value="confirmed">Confirmed setups</option><option value="watch">Watches</option><option value="issues">Unavailable / failed checks</option><option value="up">Positive daily change</option><option value="down">Negative daily change</option></select></label></div><div id="fsList"></div><div class="market-controls"><button id="fsPrev">Previous</button><span id="fsPage"></span><button id="fsNext">Next</button></div><div id="fsResults"></div><p class="small-note">All NSE equity instruments published in FYERS’ cash-market directory, including SME, preference shares and other equity series. Broker-classified indices, ETFs, bonds and derivatives are excluded. Sequential checks are paced; full-market scans take time and results have individual check times, not one simultaneous market snapshot. Keep the app open; pause/resume checkpoints are saved in this browser for up to 6 hours. No orders or background alerts are sent.</p>';
 const $=id=>host.querySelector('#'+id),message=t=>$('fsStatus').textContent=t;
 const list=()=>mode==='all'?universe.map(r=>r.symbol):custom.slice();
 const name=s=>names.get(s)||s;
 function store(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageFailed=true;return false}}
 function checkpoint(){if(scanSymbols.length)store('radar.nseScanCheckpoint',{symbols:scanSymbols,cursor,rows:[...rows.values()],startedAt,lastAt,savedAt:Date.now(),mode})}
 function restore(){try{const d=JSON.parse(localStorage.getItem('radar.nseScanCheckpoint')||'null'),symbols=list();if(!d||d.mode!==mode||!Number.isFinite(d.savedAt)||d.savedAt>Date.now()+1000||Date.now()-d.savedAt>21600000||JSON.stringify(d.symbols)!==JSON.stringify(symbols)||!Number.isInteger(d.cursor)||d.cursor<0||d.cursor>symbols.length||!Array.isArray(d.rows)||d.rows.length!==d.cursor||d.rows.some((r,i)=>!r||r.symbol!==symbols[i]||!Number.isFinite(r.at)||(r.results&&!Array.isArray(r.results))||(r.results&&r.results.some(x=>!checked(x)))))return;scanSymbols=symbols;cursor=d.cursor;rows=new Map(d.rows.map(r=>[r.symbol,r]));startedAt=d.startedAt;lastAt=d.lastAt;message(cursor===symbols.length?'Previous scan restored. Start a new scan for current checks.':'Paused scan restored. Resume from stock '+(cursor+1)+'.')}catch{}}
 async function api(path){const r=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(path.includes('/scan?')?60000:25000)});let d;try{d=await r.json()}catch{throw Error('FYERS response unreadable. Retry later.')}if(!d||typeof d!=='object'||Array.isArray(d)||!r.ok||d.error)throw Error(d?.error||'FYERS data unavailable.');return d}
 function fresh(q){return q?.valid&&Number.isFinite(q.price)&&q.price>0&&Number.isFinite(q.at)&&q.at<=Date.now()+1000&&Date.now()-q.at<=15000}
 function draw(){const symbols=list(),term=$('fsTableSearch').value.trim().toUpperCase(),filter=$('fsFilter').value;const filtered=symbols.filter(s=>{if(term&&!s.includes(term)&&!name(s).toUpperCase().includes(term))return false;const row=rows.get(s),q=quotes.get(s),result=row?.results||[];return filter==='confirmed'?result.some(r=>r.status==='Confirmed'):filter==='watch'?result.some(r=>r.status==='Watch'):filter==='issues'?!!row&&(!!row.error||result.some(r=>r.status==='Unavailable')):filter==='up'?q?.changePercent>0:filter==='down'?q?.changePercent<0:true});page=Math.min(page,Math.max(0,Math.ceil(filtered.length/50)-1));const visible=filtered.slice(page*50,page*50+50);
 $('fsList').innerHTML='<div class="market-table-scroll" tabindex="0" role="region" aria-label="NSE stock screener results"><table class="market-table"><thead><tr><th>Stock</th><th>Last price / change %</th><th>Quote source time (IST)</th><th>Strategy checks</th><th>Checked at (IST)</th><th>Actions</th></tr></thead><tbody>'+ (visible.map(s=>{const q=quotes.get(s),row=rows.get(s);return '<tr><td><b>'+esc(s)+'</b><br>'+esc(name(s))+'</td><td>'+fmt(q?.price)+' / '+fmt(q?.changePercent)+'%<br>'+esc(q?(fresh(q)?'Fresh snapshot':q.error||'Last traded / not live'):'Quote not loaded')+'</td><td>'+esc(q?.at?new Date(q.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'Unavailable')+'</td><td>'+(row?(row.error?'<p class="market-error">'+esc(row.error)+'</p>':'')+(row.results||[]).map(r=>'<details><summary>'+esc(r.strategy)+' · '+esc(r.status)+'</summary>'+esc(r.reason)+'</details>').join(''):'Not checked')+'</td><td>'+esc(row?new Date(row.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'—')+'</td><td><button data-fs-chart="'+esc(s)+'">Chart</button><button data-fs-plan="'+esc(s)+'">Plans</button>'+(mode==='custom'?'<button data-fs-remove="'+esc(s)+'" '+(running?'disabled':'')+'>Remove</button>':'')+'</td></tr>'}).join('')||'<tr><td colspan="6">No stocks match. '+(!symbols.length?'Load the directory or add stocks.':'')+'</td></tr>')+'</tbody></table></div>';
 const failures=[...rows.values()].filter(r=>r.error).length,confirmed=[...rows.values()].filter(r=>r.results?.some(x=>x.status==='Confirmed')).length;
 $('fsProgress').max=Math.max(1,scanSymbols.length);$('fsProgress').value=cursor;$('fsCoverage').textContent=cursor+' / '+(scanSymbols.length||symbols.length)+' checked · '+confirmed+' stocks with confirmed setups · '+failures+' stocks with provider errors'+(startedAt?' · scan started '+new Date(startedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'')+(storageFailed?' · Browser storage unavailable/full: progress may not survive closing.':'');
 $('fsPage').textContent=(filtered.length?page*50+1:0)+'–'+Math.min(filtered.length,(page+1)*50)+' of '+filtered.length+' matches';$('fsPrev').disabled=page===0;$('fsNext').disabled=(page+1)*50>=filtered.length;
 for(const id of ['fsScope','fsUniverse','fsAdd'])$(id).disabled=running||pending;
 $('fsScan').disabled=running||pending||!symbols.length;$('fsScan').textContent=mode==='all'?'Start full NSE scan':'Scan my saved list';$('fsQuotes').disabled=running||pending||!symbols.length;$('fsResume').disabled=running||pending||!scanSymbols.length||cursor>=scanSymbols.length;$('fsStop').disabled=!running;$('fsCustom').hidden=mode!=='custom';
 }
 function reset(){cursor=0;scanSymbols=[];rows.clear();quotes.clear();startedAt=null;lastAt=null;page=0}
 const cancelWait=()=>{if(pauseTimer!==null){clearTimeout(pauseTimer);pauseTimer=null;pauseResolve?.();pauseResolve=null}};
 const wait=ms=>new Promise(resolve=>{pauseResolve=resolve;pauseTimer=setTimeout(()=>{pauseTimer=null;pauseResolve=null;resolve()},ms)});
 async function directory(){if(running||pending)return;const id=++load; $('fsUniverse').disabled=true;try{const d=await api('/api/fyers/universe');if(!active||id!==load)return;if(!Array.isArray(d.instruments)||!d.instruments.length||d.total!==d.instruments.length||d.instruments.some(r=>!valid(r?.symbol)||!r.symbol.startsWith('NSE:')||typeof r.name!=='string')||new Set(d.instruments.map(r=>r.symbol)).size!==d.total)throw Error('NSE directory response invalid.');universe=d.instruments;names=new Map(universe.map(r=>[r.symbol,r.name]));directoryAt=d.asOf;$('fsUniverseStatus').textContent=universe.length+' NSE equity instruments · FYERS directory fetched '+new Date(directoryAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST';if(mode==='all'){reset();restore();message(cursor?'Saved checks restored. Resume unfinished checks or start a fresh scan.':'All '+universe.length+' NSE equity instruments loaded. Start full NSE scan.')}draw()}catch(e){if(active&&id===load){$('fsUniverseStatus').textContent=e.message;draw()}}finally{if(active&&id===load)$('fsUniverse').disabled=running}}
 async function scan(resume){if(running||pending||!list().length)return;if(!resume){rows.clear();cursor=0;scanSymbols=list();startedAt=Date.now();lastAt=null;checkpoint()}running=true;const id=++run;draw();try{while(cursor<scanSymbols.length){if(!active||id!==run)return;const symbol=scanSymbols[cursor];message('Scanning '+symbol+' · '+(cursor+1)+' / '+scanSymbols.length);let row;pending=true;try{const d=await api('/api/fyers/scan?symbol='+encodeURIComponent(symbol));if(!active||id!==run)return;if(d.symbol!==symbol||!Array.isArray(d.results)||d.results.some(r=>!checked(r)))throw Error('Invalid strategy result');const error=Array.isArray(d.errors)?d.errors.join(' · '):null;if(blocked(error||''))throw Error(error);row={symbol,results:d.results,error,at:Date.now()};if(d.quote?.symbol===symbol)quotes.set(symbol,d.quote)}catch(e){if(!active||id!==run)return;if(blocked(e.message)){message('Scan paused at '+symbol+': '+e.message+' Resume when the connection or broker quota is ready.');break}row={symbol,error:e.message,at:Date.now()}}finally{pending=false;if(active)draw()}
 if(!active||id!==run)return;rows.set(symbol,row);cursor++;lastAt=row.at;if(cursor%10===0)checkpoint();draw();if(cursor<scanSymbols.length)await wait(2000)}if(active&&id===run&&cursor===scanSymbols.length)message('Scan finished: '+cursor+' / '+scanSymbols.length+' checked. Review unavailable checks and individual timestamps; this is not a simultaneous market snapshot.')
 }finally{if(active&&id===run){running=false;checkpoint();draw()}}}
 $('fsScan').onclick=()=>scan(false);$('fsResume').onclick=()=>scan(true);$('fsStop').onclick=()=>{run++;running=false;cancelWait();checkpoint();message('Scan paused. '+cursor+' checks retained. Resume continues with the next unchecked stock after the current request settles.');draw()};
 $('fsQuotes').onclick=async()=>{if(running||pending||!list().length)return;running=true;const id=++run,selected=list();let loaded=0,failures=0;draw();try{for(let i=0;i<selected.length;i+=20){if(!active||id!==run)return;const batch=selected.slice(i,i+20);message('Fetching quotes · '+i+' / '+selected.length);pending=true;try{const d=await api('/api/fyers/quotes?symbols='+encodeURIComponent(batch.join(',')));if(!active||id!==run)return;if(!Array.isArray(d.quotes))throw Error('FYERS quote list unavailable');for(const s of batch){const q=d.quotes.find(q=>q?.symbol===s);quotes.set(s,q||{symbol:s,error:'Not returned by FYERS'});if(q)loaded++}}catch(e){if(!active||id!==run)return;if(blocked(e.message)){message('Quote refresh paused: '+e.message);return}failures+=batch.length;for(const s of batch)quotes.set(s,{symbol:s,error:e.message})}finally{pending=false;if(active)draw()}if(i+20<selected.length)await wait(300)}if(active&&id===run)message('Quote refresh finished: '+loaded+' / '+selected.length+' returned; '+failures+' in failed batches. Check source timestamps.')}finally{if(active&&id===run){running=false;draw()}}};
 $('fsScope').onchange=()=>{if(running||pending){$('fsScope').value=mode;return;}run++;mode=$('fsScope').value;reset();restore();draw();message(mode==='all'?'All NSE stocks selected. Start or resume the scan.':'Saved list selected. Search and add instruments.');if(mode==='all'&&!universe.length)directory()};$('fsUniverse').onclick=directory;
 $('fsFind').onclick=async()=>{const id=++search,segment=$('fsSegment').value,query=$('fsQuery').value.trim();$('fsFind').disabled=true;try{const d=await api('/api/fyers/instruments?segment='+segment+'&search='+encodeURIComponent(query));if(!active||id!==search)return;if(!Array.isArray(d.instruments))throw Error('Instrument list unavailable');$('fsMatches').innerHTML='<option value="">Choose stock</option>'+d.instruments.map(r=>'<option value="'+esc(r.symbol)+'">'+esc(r.symbol+' · '+r.name)+'</option>').join('');$('fsSearchStatus').textContent=d.total+' matches; first '+d.instruments.length+' shown.'}catch(e){if(active&&id===search)$('fsSearchStatus').textContent=e.message}finally{if(active&&id===search)$('fsFind').disabled=false}};
 $('fsQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('fsFind').click()}};$('fsSegment').onchange=()=>{search++;$('fsMatches').innerHTML='<option value="">Search this exchange</option>';$('fsFind').disabled=false};$('fsAdd').onclick=()=>{if(running||pending||mode!=='custom')return;const s=$('fsMatches').value;if(!valid(s))return message('Search and select a stock first.');if(custom.includes(s))return message(s+' is already in your list.');if(custom.length>=20)return message('Saved list supports 20 stocks. Choose All NSE stocks to scan the full universe.');custom.push(s);store('radar.fyersStockList',custom);reset();draw();message(s+' added.')};
 $('fsTableSearch').oninput=$('fsFilter').onchange=()=>{page=0;draw()};$('fsPrev').onclick=()=>{page--;draw()};$('fsNext').onclick=()=>{page++;draw()};
 const click=event=>{const b=event.target.closest('[data-fs-chart],[data-fs-plan],[data-fs-remove]');if(!b)return;if(b.dataset.fsChart)onChart(b.dataset.fsChart);if(b.dataset.fsPlan)onPlan(b.dataset.fsPlan);if(b.dataset.fsRemove&&!running&&!pending&&mode==='custom'){custom=custom.filter(s=>s!==b.dataset.fsRemove);store('radar.fyersStockList',custom);reset();draw()}};host.addEventListener('click',click);const freshness=setInterval(()=>{if(active&&!document.hidden&&quotes.size)draw()},15000);draw();directory();return ()=>{checkpoint();active=false;run++;load++;search++;clearInterval(freshness);cancelWait();host.removeEventListener('click',click)};
}};
})();
